{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

var helpText = `Cppcheck - A tool for static C/C++ code analysis

Syntax:
    cppcheck [OPTIONS] [files or paths]

If a directory is given instead of a filename, *.cpp, *.cxx, *.cc, *.c++, *.c, *.ipp,
*.ixx, *.tpp, and *.txx files are checked recursively from the given directory.

Options:
    --addon=<addon>
                         Execute addon. i.e. --addon=misra. If options must be
                         provided a json configuration is needed.
    --addon-python=<python interpreter>
                         You can specify the python interpreter either in the
                         addon json files or through this command line option.
                         If not present, Cppcheck will try "python3" first and
                         then "python".
    --cppcheck-build-dir=<dir>
                         Cppcheck work folder. Advantages:
                          * whole program analysis
                          * faster analysis; Cppcheck will reuse the results if
                            the hash for a file is unchanged.
                          * some useful debug information, i.e. commands used to
                            execute clang/clang-tidy/addons.
    --check-config       Check cppcheck configuration. The normal code
                         analysis is disabled by this flag.
    --check-level=<level>
                         Configure how much valueflow analysis you want:
                          * reduced: Reduce valueflow to finish checking quickly.
                          * normal: Cppcheck uses some compromises in the analysis so
                            the checking will finish in reasonable time.
                          * exhaustive: deeper analysis that you choose when you can
                            wait.
                         The default choice is 'normal'.
    --check-library      Show information messages when library files have
                         incomplete info.
    --checkers-report=<file>
                         Write a report of all the active checkers to the given file.
    --clang=<path>       Experimental: Use Clang parser instead of the builtin Cppcheck
                         parser. Takes the executable as optional parameter and
                         defaults to `clang`. Cppcheck will run the given Clang
                         executable, import the Clang AST and convert it into
                         Cppcheck data. After that the normal Cppcheck analysis is
                         used. You must have the executable in PATH if no path is
                         given.
    --config-exclude=<dir>
                         Path (prefix) to be excluded from configuration
                         checking. Preprocessor configurations defined in
                         headers (but not sources) matching the prefix will not
                         be considered for evaluation.
    --config-excludes-file=<file>
                         A file that contains a list of config-excludes
    --disable=<severity> Disable checks with the given severity.
                         Please refer to the documentation of --enable for
                         further details.
    --dump               Dump xml data for each translation unit. The dump
                         files have the extension .dump and contain ast,
                         tokenlist, symboldatabase, valueflow.
    -D<ID>               Define preprocessor symbol. Unless --max-configs or
                         --force is used, Cppcheck will only check the given
                         configuration when -D is used.
                         Example: '-DDEBUG=1 -D__cplusplus'.
    -E                   Print preprocessor output on stdout and don't do any
                         further processing.
    --enable=<severity>  Enable additional checks grouped by severity. The available
                         severities are:
                          * warning
                          * performance
                          * portability
                          * information
                          * style
                                  Enable checks with severities 'style', 'warning',
                                  'performance' and 'portability'.
                          * unusedFunction
                                  Check for unused functions. It is recommended
                                  to only enable this when the whole program is
                                  scanned.
                          * missingInclude
                                  Check for missing include files.
                          * all
                                  Enable all checks.
                         Pass multiple severities as a comma-separated list.
    --error-exitcode=<n> If errors are found, integer [n] is returned instead of
                         the default '0'. '1' is returned
                         if arguments are not valid or if no input files are
                         provided.
`}

var exts = map[string]bool{
	".cpp": true, 
	".cxx": true,
	".cc": true,
	".c++": true,
	".c": true,
	".ipp": true,
	".ixx": true,
	".tpp": true,
	".txx": true,
}

func main() {
	// Simple flag parsing for known flags
	showHelp := false
	showVersion := false
	errorExit := -1
	args := []string{}

	for _, a := range os.Args[1:] {
		if a == "--help" || a == "-h" {
			showHelp = true
		} else if a == "--version" || a == "-v" {
			showVersion = true
		} else if strings.HasPrefix(a, "--error-exitcode=") {
			v := strings.TrimPrefix(a, "--error-exitcode=")
			if n, err := strconv.Atoi(v); err == nil {
				errorExit = n
			}
		} else if strings.HasPrefix(a, "-") {
			// ignore unknown flags
			// but keep them out of args
		} else {
			args = append(args, a)
		}
	}

	if showVersion {
		fmt.Println("Cppcheck 2.19 dev")
		os.Exit(0)
	}

	if showHelp || len(args) == 0 {
		fmt.Print(helpText)
		os.Exit(0)
	}

	// Collect files
	files := []string{}
	for _, a := range args {
		fi, err := os.Stat(a)
		if err != nil {
			// treat non-existent as literal file
			files = append(files, a)
			continue
		}
		if fi.IsDir() {
			_ = filepath.WalkDir(a, func(p string, d fs.DirEntry, err error) error {
				if err != nil { return nil }
				if d.IsDir() { return nil }
				ext := strings.ToLower(filepath.Ext(p))
				if exts[ext] {
					files = append(files, p)
				}
				return nil
			})
		} else {
			files = append(files, a)
		}
	}

	// sort for deterministic output
	sort.Strings(files)

	hadErrors := false
	for i, f := range files {
		fmt.Printf("Checking %s...\n", f)
		errs := analyzeFile(f)
		for _, e := range errs {
			fmt.Println(e)
			hadErrors = true
		}
		// Progress messages: print progress if multiple files
		if len(files) > 1 && i+1 < len(files) {
			pct := (i + 1) * 100 / len(files)
			fmt.Printf("%d/%d files checked %d%% done\n", i+1, len(files), pct)
		}
	}

	if hadErrors && errorExit >= 0 {
		os.Exit(errorExit)
	}
	// default exit 0
}

func analyzeFile(path string) []string {
	f, err := os.Open(path)
	if err != nil {
		// if cannot open, return nothing
		return nil
	}
	defer f.Close()

	// read line by line
	r := bufio.NewReader(f)
	lines := []string{}
	for {
		ln, err := r.ReadString('\n')
		ln = strings.TrimRight(ln, "\r\n")
		if len(ln) > 0 || err == nil {
			lines = append(lines, ln)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			break
		}
	}

	// find declarations like 'char a[10];' or 'int arr[5];'
	declRe := regexp.MustCompile(`\b([A-Za-z_]\w*)\s*\[\s*([0-9]+)\s*\]`)
	assignRe := regexp.MustCompile(`\b([A-Za-z_]\w*)\s*\[\s*([0-9]+)\s*\]`)
	// map name->size
	decls := map[string]int{}
	for _, ln := range lines {
		// remove any leading type keywords roughly by looking for typical types
		// but simply capture all bracketed declarations
		m := declRe.FindAllStringSubmatch(ln, -1)
		if m != nil {
			for _, sub := range m {
				name := sub[1]
				size, _ := strconv.Atoi(sub[2])
				// store if not present (first is likely declaration)
				if size > 0 && decls[name] == 0 {
					decls[name] = size
				}
			}
		}
	}

	errs := []string{}
	for i, ln := range lines {
		m := assignRe.FindAllStringSubmatch(ln, -1)
		if m != nil {
			for _, sub := range m {
				name := sub[1]
				idx, _ := strconv.Atoi(sub[2])
				if size, ok := decls[name]; ok {
					if idx >= size {
						// produce message
						msg := fmt.Sprintf("[%s:%d]: (error) Array '%s[%d]' index %d out of bounds", path, i+1, name, size, idx)
						errs = append(errs, msg)
					}
				}
			}
		}
	}

	return errs
}
EOF

cat <<'EOF' > compile.sh
#!/usr/bin/env bash
set -euo pipefail

# Build the Go program into ./executable
if ! command -v go >/dev/null 2>&1; then
    echo "Go toolchain is required to build this program" >&2
    exit 1
fi

go build -o executable main.go
chmod +x executable
EOF

cat <<'EOF' > .gitignore
/executable
EOF

chmod +x compile.sh

# quick test: create example file and run
cat <<'EOF' > file1.c
int main()
{
    char a[10];
    a[10] = 0;
    return 0;
}
EOF

./compile.sh >/dev/null

./executable file1.c | sed -n '1,200p'
"}

