			files = append(files, a)
			continue
		}
		if fi.IsDir() {
			_ = filepath.WalkDir(a, func(p string, d fs.DirEntry, err error) error {
				if err != nil { return nil }
				if d.IsDir() { return nil }
				ext := strings.ToLower(filepath.Ext(p))
				if exts[ext] {
					files = append(files, p)
				}
				return nil
			})
		} else {
			files = append(files, a)
		}
	}

	// sort for deterministic output
	sort.Strings(files)

	hadErrors := false
	for i, f := range files {
		fmt.Printf("Checking %s...\n", f)
		errs := analyzeFile(f)
		for _, e := range errs {
			fmt.Println(e)
			hadErrors = true
		}
		// Progress messages: print progress if multiple files
		if len(files) > 1 && i+1 < len(files) {
			pct := (i + 1) * 100 / len(files)
			fmt.Printf("%d/%d files checked %d%% done\n", i+1, len(files), pct)
		}
	}

	if hadErrors && errorExit >= 0 {
		os.Exit(errorExit)
	}
	// default exit 0
}

func analyzeFile(path string) []string {
	f, err := os.Open(path)
	if err != nil {
		// if cannot open, return nothing
		return nil
	}
	defer f.Close()

	// read line by line
	r := bufio.NewReader(f)
	lines := []string{}
	for {
		ln, err := r.ReadString('\n')
		ln = strings.TrimRight(ln, "\r\n")
		if len(ln) > 0 || err == nil {
			lines = append(lines, ln)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			break
		}
	}

	// find declarations like 'char a[10];' or 'int arr[5];'
	declRe := regexp.MustCompile(`\b([A-Za-z_]\w*)\s*\[\s*([0-9]+)\s*\]`)
	assignRe := regexp.MustCompile(`\b([A-Za-z_]\w*)\s*\[\s*([0-9]+)\s*\]`)
	// map name->size
	decls := map[string]int{}
	for _, ln := range lines {
		// remove any leading type keywords roughly by looking for typical types
		// but simply capture all bracketed declarations
		m := declRe.FindAllStringSubmatch(ln, -1)
		if m != nil {
			for _, sub := range m {
				name := sub[1]
				size, _ := strconv.Atoi(sub[2])
				// store if not present (first is likely declaration)
				if size > 0 && decls[name] == 0 {
					decls[name] = size
				}
			}
		}
	}

	errs := []string{}
	for i, ln := range lines {
		m := assignRe.FindAllStringSubmatch(ln, -1)
		if m != nil {
			for _, sub := range m {
				name := sub[1]
				idx, _ := strconv.Atoi(sub[2])
				if size, ok := decls[name]; ok {
					if idx >= size {
						// produce message
						msg := fmt.Sprintf("[%s:%d]: (error) Array '%s[%d]' index %d out of bounds", path, i+1, name, size, idx)
						errs = append(errs, msg)
					}
				}
			}
		}
	}

	return errs
}
